fn record(cp: u21) Record {
    if (cp > 0x10ffff) return @bitCast(@as(u16, 0x280));
    const block = index[cp >> 8];
    return @bitCast(data[(@as(usize, block) << 8) | (cp & 0xff)]);
}
pub fn eastAsianWidth(cp: u21) EastAsianWidth { return record(cp).eaw; }
pub fn isEmojiPresentation(cp: u21) bool { return record(cp).emoji_presentation; }
pub fn isEmojiVariationBase(cp: u21) bool { return record(cp).emoji_vs_base; }
pub fn isEmojiModifier(cp: u21) bool { return record(cp).emoji_modifier; }
pub fn isEmojiModifierBase(cp: u21) bool { return record(cp).emoji_modifier_base; }
pub fn widthProperties(cp: u21) WidthProperties { const r = record(cp); return .{ .standalone = r.standalone, .zero_in_grapheme = r.zero_in_grapheme, .emoji_modifier = r.emoji_modifier }; }
